SELECT "semantic_contacts"."agent_site" AS "dim_value", COUNT(*) AS "n" FROM "gold"."semantic_contacts" AS "semantic_contacts" WHERE "semantic_contacts"."direction" = 'outbound' AND "semantic_contacts"."channel" = 'call' AND "semantic_contacts"."contact_ts_local" >= $start AND "semantic_contacts"."contact_ts_local" < $end GROUP BY "semantic_contacts"."agent_site" LIMIT 500
